	// AssignmentOperator<collapsed>= assign | mul_assign | div_assign | mod_assign | add_assign | sub_assign | shl_assign | shr_assign | ushr_assign | and_assign | xor_assign | or_assign;
	void ParseAssignmentOperator(ParseNode parent)
	{
		Enter(AssignmentOperator);
		switch (Current.SymbolId)
		{
			case Assign:
			case MulAssign:
			case DivAssign:
			case ModAssign:
			case AddAssign:
			case SubAssign:
			case ShlAssign:
			case ShrAssign:
			case UshrAssign:
			case AndAssign:
			case XorAssign:
			case OrAssign:
				Consume(parent);
				break;
			default:
				Error(parent, null, Assign, AddAssign, SubAssign, MulAssign, ModAssign, ShlAssign, ShrAssign, UshrAssign, AndAssign, OrAssign, XorAssign, DivAssign);
				break;
		}
		Leave();
	}

	// Expression= AssignmentExpression { comma AssignmentExpression };
	ParseNode ParseExpression()
	{
		Enter(Expression);
		var node = NewNode(Expression);
		node.Add(ParseAssignmentExpression());
		// { comma AssignmentExpression }
		while (Current.SymbolId == Comma)
		{
			Consume(node);
			node.Add(ParseAssignmentExpression());
		}
		Leave();
		return node;
	}

	// ExpressionNoIn= AssignmentExpressionNoIn { comma AssignmentExpressionNoIn };
	ParseNode ParseExpressionNoIn()
	{
		Enter(ExpressionNoIn);
		var node = NewNode(ExpressionNoIn);
		node.Add(ParseAssignmentExpressionNoIn());
		// { comma AssignmentExpressionNoIn }
		while (Current.SymbolId == Comma)
		{
			Consume(node);
			node.Add(ParseAssignmentExpressionNoIn());
		}
		Leave();
		return node;
	}

	// Identifier<collapsed>= identifier;
	void ParseIdentifier(ParseNode parent)
	{
		Enter(Identifier);
		Expect(Identifier2, parent);
		Leave();
	}

