				{
					case Break:
					case Case:
					case Catch2:
					case Continue:
					case Debugger:
					case Default:
					case Delete:
					case Do:
					case Else:
					case Finally2:
					case For:
					case Function:
					case If:
					case In:
					case Instanceof:
					case New:
					case Return:
					case Switch:
					case This:
					case Throw:
					case Try:
					case Typeof:
					case Var:
					case Void:
					case While:
					case With:
					case Class:
					case Const:
					case Enum:
					case Export:
					case Extends:
					case Import:
					case Super:
					case Null:
					case True:
					case False:
					case Identifier2:
					case NumericLiteral:
					case StringLiteral:
						return 0;
					case Rbrace:
						return 1;
				}
				break;
		}
		return -1;
	}

